<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Notificaciones | CampoSur</title><link rel="stylesheet" href="/assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><?php require dirname(__DIR__) . '/Views/partials/module-navigation.php'; ?><header class="admin-header"><div><p class="eyebrow">Centro de actividad</p><h1>Notificaciones <span class="tag"><?= $unreadCount ?></span></h1><p class="setup-copy">Alertas y recordatorios de la operación agrícola.</p></div><a class="secondary-link" href="/">Volver al dashboard</a></header><?php if ($error): ?><div class="setup-error"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="read_all"><button class="secondary-link" type="submit">Marcar todas como leídas</button></form><section class="admin-panel"><table class="data-table"><thead><tr><th>Fecha</th><th>Tipo</th><th>Título</th><th>Mensaje</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach ($notifications as $notification): ?><tr><td><?= htmlspecialchars($notification['created_at'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($notification['notification_type'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($notification['title'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($notification['message'], ENT_QUOTES, 'UTF-8') ?></td><td><?= $notification['read_at'] ? 'Leída' : 'Pendiente' ?></td><td><?php if (!$notification['read_at']): ?><form method="post"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="read"><input type="hidden" name="notification_id" value="<?= (int) $notification['id'] ?>"><button class="button-link" type="submit">Marcar leída</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></section></main></body></html>
